<script setup lang="ts">
import { ref, watch, onUnmounted } from 'vue'; import { useRoute } from 'vue-router'; import Button from 'primevue/button'; import InputText from 'primevue/inputtext'; import Select from 'primevue/select'; import Dialog from 'primevue/dialog'; import Textarea from 'primevue/textarea'; import DataTable from 'primevue/datatable'; import Column from 'primevue/column'; import { useToast } from 'primevue/usetoast'; import { api, currentUser } from '../lib/api'; import { initials, serviceNames, date, type Data } from '../lib/types'; import { useQuery } from '../composables/useQuery'; import StatusBadge from '../components/StatusBadge.vue'; import DriverDocuments from '../components/DriverDocuments.vue'; import QueryState from '../components/QueryState.vue';
const route = useRoute(), toast = useToast(), search = ref(''), status = ref<string | null>(String(route.query.status ?? '') || null), selected = ref<Data>(), show = ref(false), decision = ref('APPROVED'), reason = ref(''), busy = ref(false);
const {data,loading,error,refresh} = useQuery(() => api('/admin/drivers?' + new URLSearchParams({ ...(search.value ? {q:search.value}:{}), ...(status.value ? {status:status.value}:{}) }))); let timer: ReturnType<typeof setTimeout> | undefined; watch([search,status], () => { clearTimeout(timer); timer = setTimeout(refresh,350); });
onUnmounted(() => clearTimeout(timer));
async function review() { if(!selected.value) return; busy.value=true; try { await api('/admin/drivers/'+selected.value.id+'/review-decisions',{method:'POST',body:{expectedVersion:selected.value.version,decision:decision.value,reasonCode:reason.value}}); show.value=false; await refresh(); toast.add({severity:'success',summary:'Đã ghi nhận kết quả xét duyệt',life:3000}); } catch(e){ toast.add({severity:'error',summary:(e as Error).message,life:5000}); } finally{busy.value=false;} }
</script>
<template><div class="page-heading"><div><div class="eyebrow">CỘNG ĐỒNG ĐỐI TÁC</div><h1>Đối tác tài xế<span class="green-text">.</span></h1><p>Đồng hành cùng những người kết nối thành phố.</p></div><span class="date-pill"><i class="pi pi-id-card"></i>{{ data?.items.length ?? 0 }} đối tác</span></div><div class="inline-stats"><div><span class="metric-icon green"><i class="pi pi-verified"></i></span><div><strong>{{ data?.items.filter((d:Data)=>d.reviewStatus==='APPROVED').length ?? 0 }}</strong><span>Đã được duyệt</span></div></div><div><span class="metric-icon orange"><i class="pi pi-clock"></i></span><div><strong>{{ data?.items.filter((d:Data)=>d.reviewStatus==='PENDING_REVIEW').length ?? 0 }}</strong><span>Hồ sơ chờ duyệt</span></div></div><div><span class="metric-icon blue"><i class="pi pi-wifi"></i></span><div><strong>{{ data?.items.filter((d:Data)=>d.healthy).length ?? 0 }}</strong><span>Đang sẵn sàng</span></div></div></div><section class="panel"><div class="filter-bar"><span class="search-input"><i class="pi pi-search"></i><InputText v-model="search" placeholder="Tìm tên tài xế, biển số…" aria-label="Tìm tài xế"/></span><Select v-model="status" aria-label="Lọc trạng thái hồ sơ" :options="[{label:'Tất cả hồ sơ',value:null},{label:'Chờ xét duyệt',value:'PENDING_REVIEW'},{label:'Đã duyệt',value:'APPROVED'},{label:'Cần bổ sung',value:'REJECTED'}]" option-label="label" option-value="value"/><Button icon="pi pi-refresh" text severity="secondary" aria-label="Làm mới" @click="refresh"/></div><QueryState :loading="loading" :error="error" @retry="refresh"/><DataTable v-if="data" :value="data.items" paginator :rows="10" class="grap-table" row-hover><template #empty><div class="table-empty">Không có tài xế phù hợp.</div></template><Column header="ĐỐI TÁC"><template #body="{data:d}"><div class="person-cell"><span class="avatar lavender">{{ initials(d.name) }}</span><div><strong>{{d.name}}</strong><small>{{d.phone}}</small></div></div></template></Column><Column header="PHƯƠNG TIỆN"><template #body="{data:d}"><strong>{{d.vehicle}}</strong><small class="cell-muted">{{d.plate}} · {{d.color}}</small></template></Column><Column header="DỊCH VỤ"><template #body="{data:d}"><span class="service-chip"><i class="pi" :class="d.serviceTypeCode==='BIKE'?'pi-directions':'pi-car'"></i>{{serviceNames[d.serviceTypeCode]}}</span></template></Column><Column header="ĐÁNH GIÁ"><template #body="{data:d}"><span class="rating"><i class="pi pi-star-fill"></i> {{d.rating.toFixed(1)}}</span></template></Column><Column header="HỒ SƠ"><template #body="{data:d}"><StatusBadge :status="d.reviewStatus"/></template></Column><Column header="HOẠT ĐỘNG"><template #body="{data:d}"><span class="availability"><i :class="d.healthy?'available':'offline'"></i>{{d.onRide?'Đang có chuyến':d.healthy?'Sẵn sàng':d.online?'GPS / kết nối cũ':'Ngoại tuyến'}}</span></template></Column><Column><template #body="{data:d}"><Button :label="d.reviewStatus==='PENDING_REVIEW'?'Xét duyệt':'Chi tiết'" text size="small" @click="selected=d;show=true;reason='';decision='APPROVED'"/></template></Column></DataTable></section><Dialog v-model:visible="show" modal header="Hồ sơ đối tác tài xế" :style="{width:'560px'}"><template v-if="selected"><div class="detail-title"><div class="person-cell"><span class="avatar large mint">{{initials(selected.name)}}</span><div><h2>{{selected.name}}</h2><p>{{selected.phone}}</p></div></div><StatusBadge :status="selected.reviewStatus"/></div><div class="detail-grid"><div><span>Phương tiện</span><strong>{{selected.vehicle}}</strong></div><div><span>Biển kiểm soát</span><strong>{{selected.plate}}</strong></div><div><span>Hạn giấy tờ</span><strong>{{date(selected.documentsExpireAt,false)}}</strong></div><div><span>Vị trí cập nhật cuối</span><strong>{{date(selected.locationAt)}}</strong></div></div><div class="info-box"><i class="pi pi-info-circle"></i><p>Hồ sơ local dùng dữ liệu minh họa. File đính kèm được lưu private và chỉ người có quyền xét duyệt mới được xem. Cần storage/scanning provider trước khi tiếp nhận hồ sơ thật.</p></div><DriverDocuments v-if="currentUser?.role==='DriverReviewer'" :key="selected.id" :driver-id="selected.id"/><template v-if="selected.reviewStatus==='PENDING_REVIEW' && currentUser?.role==='DriverReviewer'"><label>Kết quả xét duyệt<Select v-model="decision" :options="[{label:'Chấp thuận hồ sơ mẫu',value:'APPROVED'},{label:'Yêu cầu bổ sung',value:'REJECTED'}]" option-label="label" option-value="value" class="full-width"/></label><label>Nhận xét bắt buộc<Textarea v-model="reason" rows="3" class="full-width"/></label></template><p v-else-if="selected.reviewStatus==='PENDING_REVIEW'" class="muted">Đăng nhập vai trò Xét duyệt tài xế để xử lý hồ sơ.</p><p v-if="selected.reviewReason" class="muted">Kết quả gần nhất: {{selected.reviewReason}}</p></template><template #footer><Button label="Đóng" text severity="secondary" @click="show=false"/><Button v-if="currentUser?.role==='DriverReviewer' && selected?.reviewStatus==='PENDING_REVIEW'" label="Lưu kết quả" :loading="busy" :disabled="reason.trim().length<3" @click="review"/></template></Dialog></template>
